53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const BLOCK_SIZE = 3;
66	const COMPONENT_BLOCK_PREMIUM = 60;
67	
68	const COMPONENT_TYPES = ["rune", "moonstone"];
69	
70	const componentBlockAdjustment = (
71	  items: Item[],
72	  componentType: string,
73	): number => {
74	  const count = items.filter((item) => item.type === componentType).length;
75	  return count === BLOCK_SIZE
76	    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * BASE_PREMIUMS[componentType]
77	    : 0;
78	};
79	
80	const basePremiumFor = (items: Item[]): number =>
81	  items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0) +
82	  COMPONENT_TYPES.reduce(
83	    (total, componentType) => total + componentBlockAdjustment(items, componentType),
84	    0,
85	  );
86	
87	const curseSurchargeFor = (items: Item[]): number =>
88	  items.reduce(
89	    (total, item) =>
90	      total + (item.cursed ? CURSE_SURCHARGE_RATE * BASE_PREMIUMS[item.type] : 0),
91	    0,
92	  );
93	
94	const enchantmentSurchargeFor = (items: Item[]): number =>
95	  items.reduce(
96	    (total, item) =>
97	      total +
98	      ((item.enchantment ?? 0) >= 5 ? 0.3 * BASE_PREMIUMS[item.type] : 0),
99	    0,
100	  );
101	
102	const quotePremium = (basePremium: number, itemSurcharges: number): number => {
103	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
104	  return Math.ceil(
105	    basePremium + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
106	  );
107	};
