109	export const runScenario = (scenario: Scenario): ScenarioOutput => {
110	  const quoteStep = scenario.steps[0] as QuoteStep;
111	  const premium = quotePremium(
112	    basePremiumFor(quoteStep.items),
113	    curseSurchargeFor(quoteStep.items) +
114	      enchantmentSurchargeFor(quoteStep.items),
115	  );
116	  return { results: [{ premium }] };
117	};
