const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const surchargeFor = (
  items: Item[],
  rate: number,
  applies: (item: Item) => boolean,
): number =>
  items.reduce(
    (total, item) =>
      total + (applies(item) ? rate * BASE_PREMIUMS[item.type] : 0),
    0,
  );

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const curseSurchargeFor = (items: Item[]): number =>
  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);

const highEnchantmentSurchargeFor = (items: Item[]): number =>
  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);
